using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Object=UnityEngine.Object;
namespace RoadGunner.ConceptArt.Editor {
 public static class ArtKit {
 public const string Root="Assets/RoadGunner/Art/ConceptWasteland";static Dictionary<string,Material> materials=new Dictionary<string,Material>();static Dictionary<string,Mesh> primitives=new Dictionary<string,Mesh>();
 public static Color Color(string hex){ColorUtility.TryParseHtmlString("#"+hex,out var c);return c;}
 public static void Ensure(){foreach(string f in new[]{"Materials","Meshes","Prefabs","Textures","Presets"})Directory.CreateDirectory(Root+"/"+f);if(materials.Count>0)return;if(!AssetDatabase.IsValidFolder(Root))AssetDatabase.Refresh();
 string[] keys={"Sand","SandLight","SandShade","Track","Rock","RockLight","RockShade","Teal","TealLight","TealDark","Ivory","IvoryShade","Rust","RustDark","Steel","SteelLight","Rubber","RubberEdge","Cloth","Scarf","Skin","Glass","Wood","WoodLight","Mint","Glow","Red","Yellow","Cactus","DryLeaves"};string[] colors={"FF9F59","FFBE7D","E79A57","FD9D58","C67D54","D69465","A96549","397C7B","508F89","2F5D60","D8CFB6","B8AD94","AD603B","77452F","303A3C","788184","252A2B","434641","59574A","914334","AF8062","496366","846246","AE8760","85D6AD","FFCF75","914334","D3AB5B","727A3E","A49A58"};
 for(int i=0;i<keys.Length;i++){string path=Root+"/Materials/"+keys[i]+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=keys[i]};AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",Color(colors[i]));m.SetFloat("_Metallic",keys[i].StartsWith("Steel")?.65f:keys[i].StartsWith("Teal")||keys[i].StartsWith("Rust")||keys[i].StartsWith("Ivory")?.18f:0);m.SetFloat("_Smoothness",keys[i].StartsWith("Steel")?.32f:keys[i]=="Glass"?.5f:keys[i].StartsWith("Teal")||keys[i].StartsWith("Ivory")?.23f:keys[i].StartsWith("Rubber")?.11f:.09f);m.enableInstancing=true;materials[keys[i]]=m;EditorUtility.SetDirty(m);}
 foreach(string k in new[]{"Glow","Mint"}){var m=materials[k];m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",m.GetColor("_BaseColor")*(k=="Glow"?.3f:.11f));}AssetDatabase.SaveAssets();}
 public static Material Mat(string key){Ensure();if(materials.TryGetValue(key,out var m))return m;throw new ArgumentException("Unknown palette key: "+key);}
 public static GameObject Node(string name,Transform parent=null){var g=new GameObject(name);if(parent)g.transform.SetParent(parent,false);return g;}
 public static Transform Part(Transform parent,string name,Mesh mesh,Vector3 pos,Vector3 size,string material,Quaternion? rotation=null){var t=Node(name,parent).transform;t.localPosition=pos;t.localScale=size;t.localRotation=rotation??Quaternion.identity;t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=Mat(material);return t;}
 public static Transform Box(Transform parent,string name,Vector3 pos,Vector3 size,string material,float bevel=.06f,Quaternion? rotation=null){string k="Box_"+size.ToString("F4")+"_"+bevel;Mesh m;if(!primitives.TryGetValue(k,out m)||!m){m=RoundedBox(size,Mathf.Min(bevel,Mathf.Min(size.x,size.y,size.z)*.3f));primitives[k]=m;}return Part(parent,name,m,pos,Vector3.one,material,rotation);}
 static Mesh RoundedBox(Vector3 size,float radius){var verts=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();Vector3 h=size*.5f;radius=Mathf.Max(.0001f,radius);Vector3 inner=h-Vector3.one*radius;Vector3[] normal={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};Vector3[] us={Vector3.back,Vector3.forward,Vector3.right,Vector3.right,Vector3.right,Vector3.left};Vector3[] vs={Vector3.up,Vector3.up,Vector3.back,Vector3.forward,Vector3.up,Vector3.up};for(int f=0;f<6;f++){var n=normal[f];var u=us[f];var v=vs[f];float hu=Mathf.Abs(Vector3.Dot(h,u)),hv=Mathf.Abs(Vector3.Dot(h,v)),hn=Mathf.Abs(Vector3.Dot(h,n));float[] a={-hu,-hu+radius,hu-radius,hu},b={-hv,-hv+radius,hv-radius,hv};int start=verts.Count;for(int y=0;y<4;y++)for(int x=0;x<4;x++){Vector3 p=n*hn+u*a[x]+v*b[y];Vector3 q=new Vector3(Mathf.Clamp(p.x,-inner.x,inner.x),Mathf.Clamp(p.y,-inner.y,inner.y),Mathf.Clamp(p.z,-inner.z,inner.z));var d=(p-q).normalized;verts.Add(q+d*radius);normals.Add(d);uv.Add(new Vector2(x/3f,y/3f));}for(int y=0;y<3;y++)for(int x=0;x<3;x++){int i=start+y*4+x;tri.AddRange(new[]{i,i+1,i+4,i+1,i+5,i+4});}}return MeshOf("Soft beveled box",verts,tri,normals,uv);}
 public static Transform Cylinder(Transform parent,string name,Vector3 pos,float radius,float height,string material,Quaternion? rotation=null,int segments=16){string k=$"Cylinder_{radius:F4}_{height:F4}_{segments}";if(!primitives.TryGetValue(k,out var m)||!m){m=CylinderMesh(radius,height,segments);primitives[k]=m;}return Part(parent,name,m,pos,Vector3.one,material,rotation);}
 static Mesh CylinderMesh(float radius,float height,int n){var v=new List<Vector3>();var norm=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();float b=Mathf.Min(radius*.13f,height*.14f);float[] r={radius-b,radius,radius,radius-b},y={-height/2,-height/2+b,height/2-b,height/2};for(int row=0;row<4;row++)for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;v.Add(new Vector3(Mathf.Cos(a)*r[row],y[row],Mathf.Sin(a)*r[row]));norm.Add(new Vector3(Mathf.Cos(a),row==0?-.7f:row==3?.7f:0,Mathf.Sin(a)).normalized);uv.Add(new Vector2(i/(float)n,row/3f));}for(int row=0;row<3;row++)for(int i=0;i<n;i++){int a=row*(n+1)+i,b0=a+n+1;tr.AddRange(new[]{a,b0,a+1,a+1,b0,b0+1});}foreach(int s in new[]{-1,1}){int center=v.Count;v.Add(new Vector3(0,s*height/2,0));norm.Add(Vector3.up*s);uv.Add(Vector2.one*.5f);for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;v.Add(new Vector3(Mathf.Cos(a)*(radius-b),s*height/2,Mathf.Sin(a)*(radius-b)));norm.Add(Vector3.up*s);uv.Add(new Vector2(Mathf.Cos(a),Mathf.Sin(a))*.5f+Vector2.one*.5f);}for(int i=0;i<n;i++)if(s>0)tr.AddRange(new[]{center,center+i+2,center+i+1});else tr.AddRange(new[]{center,center+i+1,center+i+2});}return MeshOf("Chamfered cylinder",v,tr,norm,uv);}
 public static Transform Ellipsoid(Transform parent,string name,Vector3 pos,Vector3 size,string material,int segments=12,int rings=8){string k=$"Ellipsoid_{size:F4}_{segments}_{rings}";if(!primitives.TryGetValue(k,out var m)||!m){var v=new List<Vector3>();var norm=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();for(int y=0;y<=rings;y++)for(int x=0;x<=segments;x++){float a=x*Mathf.PI*2/segments,b=y*Mathf.PI/rings;var p=new Vector3(Mathf.Sin(b)*Mathf.Cos(a),Mathf.Cos(b),Mathf.Sin(b)*Mathf.Sin(a));v.Add(Vector3.Scale(p,size)*.5f);norm.Add(new Vector3(p.x/Mathf.Max(.001f,size.x),p.y/Mathf.Max(.001f,size.y),p.z/Mathf.Max(.001f,size.z)).normalized);uv.Add(new Vector2(x/(float)segments,y/(float)rings));}for(int y=0;y<rings;y++)for(int x=0;x<segments;x++){int a=y*(segments+1)+x,b=a+segments+1;tr.AddRange(new[]{a,a+1,b,a+1,b+1,b});}m=MeshOf("Stylized ellipsoid",v,tr,norm,uv);primitives[k]=m;}return Part(parent,name,m,pos,Vector3.one,material);}
 public static Transform Torus(Transform parent,string name,Vector3 pos,float outerRadius,float innerRadius,float width,string material,Quaternion? rotation=null,int segments=24){string k=$"Ring_{outerRadius:F4}_{innerRadius:F4}_{width:F4}_{segments}";if(!primitives.TryGetValue(k,out var m)||!m){int cross=10;float major=(outerRadius+innerRadius)*.5f,minor=(outerRadius-innerRadius)*.5f,half=width*.5f;var v=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();for(int u=0;u<=segments;u++)for(int j=0;j<=cross;j++){float a=u*Mathf.PI*2/segments,b=j*Mathf.PI*2/cross;float r=major+minor*Mathf.Cos(b);v.Add(new Vector3(Mathf.Cos(a)*r,Mathf.Sin(b)*half,Mathf.Sin(a)*r));normals.Add(new Vector3(Mathf.Cos(a)*Mathf.Cos(b)/minor,Mathf.Sin(b)/half,Mathf.Sin(a)*Mathf.Cos(b)/minor).normalized);uv.Add(new Vector2(u/(float)segments,j/(float)cross));}for(int u=0;u<segments;u++)for(int j=0;j<cross;j++){int a=u*(cross+1)+j,b=a+cross+1;tr.AddRange(new[]{a,a+1,b,a+1,b+1,b});}m=MeshOf("Rounded rubber torus",v,tr,normals,uv);primitives[k]=m;}return Part(parent,name,m,pos,Vector3.one,material,rotation);}
 public static Transform Beam(Transform parent,string name,Vector3 a,Vector3 b,float width,string material){var t=Box(parent,name,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),material,Mathf.Min(width*.15f,.035f));t.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);return t;}
 static Mesh MeshOf(string name,List<Vector3> v,List<int> t,List<Vector3> normals,List<Vector2> uv){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.SetNormals(normals);m.SetUVs(0,uv);m.RecalculateBounds();return m;}
 public static Mesh SaveMesh(Mesh mesh,string name){Ensure();string safe=string.Concat(name.Select(c=>char.IsLetterOrDigit(c)||c=='_'||c=='-'?c:'_'));string path=Root+"/Meshes/"+safe+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);mesh.name=name;if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;if(mesh.colors.Length>0)old.colors=mesh.colors;old.subMeshCount=mesh.subMeshCount;for(int sub=0;sub<mesh.subMeshCount;sub++)old.SetTriangles(mesh.GetTriangles(sub),sub);old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);if(mesh!=old)Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 public static void Bake(Transform root,string name){var filters=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh).ToArray();if(filters.Length==0)return;var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var f in filters){var r=f.GetComponent<MeshRenderer>();if(!r||r.sharedMaterials.Length==0)continue;for(int sub=0;sub<f.sharedMesh.subMeshCount;sub++){var mat=r.sharedMaterials[Math.Min(sub,r.sharedMaterials.Length-1)];if(!mat)continue;if(!groups.ContainsKey(mat))groups[mat]=new List<CombineInstance>();groups[mat].Add(new CombineInstance{mesh=f.sharedMesh,subMeshIndex=sub,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix});}}
 if(groups.Count==0)return;var pieces=new List<Mesh>();foreach(var pair in groups){var piece=new Mesh{indexFormat=IndexFormat.UInt32};piece.CombineMeshes(pair.Value.ToArray(),true,true);pieces.Add(piece);}var result=new Mesh{indexFormat=IndexFormat.UInt32};result.CombineMeshes(pieces.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,true);result=SaveMesh(result,name);foreach(var f in filters){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}var target=Node("Finished shared visuals",root);target.AddComponent<MeshFilter>().sharedMesh=result;target.AddComponent<MeshRenderer>().sharedMaterials=groups.Keys.ToArray();ConceptEnemies.BakeAtlas(target.transform,name+"_Palette");foreach(var m in pieces)Object.DestroyImmediate(m);}
 }
}
